///
/// Merging follows the ordering `Present` > `Possible` > `Absent`, so a
/// definite side effect always dominates a merge.
#[derive(Copy, Clone, Debug, Eq, PartialEq)]
pub enum SideEffect {
    /// The expression is definitely side-effect-free.
    Absent,
    /// The expression may have side effects (e.g. an f-string interpolation may
    /// invoke `__format__` or `__str__`).
    Possible,
    /// The expression is assumed to have definite side effects (e.g. a walrus
    /// operator or a function call).
    Present,
}

impl SideEffect {
    /// Returns `true` only for [`SideEffect::Present`].
    pub const fn is_present(self) -> bool {
        matches!(self, SideEffect::Present)
    }

    /// Returns `true` only for [`SideEffect::Absent`].
    pub const fn is_absent(self) -> bool {
        matches!(self, SideEffect::Absent)
    }

    /// Combine two [`SideEffect`] values, with `Present` winning over `Possible`
    /// winning over `Absent`.
    #[must_use]
    pub const fn merge(self, other: Self) -> Self {
        match (self, other) {
            (SideEffect::Present, _) | (_, SideEffect::Present) => SideEffect::Present,
            (SideEffect::Possible, _) | (_, SideEffect::Possible) => SideEffect::Possible,
            (SideEffect::Absent, SideEffect::Absent) => SideEffect::Absent,
        }
    }
}

/// Return the combined [`SideEffect`] of an expression and all of its
/// sub-expressions.
///
/// An f-string that interpolates any non-literal expression is classified as
/// [`SideEffect::Possible`], since evaluating the interpolation may invoke
/// `__format__` or `__str__`. A named expression (walrus operator), function
/// call, subscript, `await`, `yield`, comprehension, and other complex
/// expressions are classified as [`SideEffect::Present`]. Everything else is
/// [`SideEffect::Absent`].
///
/// The traversal short-circuits and returns [`SideEffect::Present`] as soon as
/// a `Present` sub-expression is found.
///
/// Accepts a closure that determines whether a given name (e.g., `"list"`) is a Python builtin.
pub fn side_effect<F>(expr: &Expr, is_builtin: F) -> SideEffect
where
    F: Fn(&str) -> bool,
{
    let mut effect = SideEffect::Absent;
    any_over_expr(expr, |expr| {
        effect = effect.merge(expr_side_effect(expr, &is_builtin));
        effect.is_present()
    });
    effect
}

/// Classify a single expression node (without recursing into its children).
fn expr_side_effect<F>(expr: &Expr, is_builtin: &F) -> SideEffect
where
    F: Fn(&str) -> bool,
{
    // A named expression (walrus operator) always has a side effect.
    if expr.is_named_expr() {
        return SideEffect::Present;
    }

    // An f-string that interpolates a non-literal expression may have a side effect,
    // since evaluating the interpolation can invoke `__format__` or `__str__`.
    if let Expr::FString(ast::ExprFString { value, .. }) = expr {
        if value.elements().any(|element| {
            element
                .as_interpolation()
                .is_some_and(|interpolation| !interpolation.expression.is_literal_expr())
        }) {
            return SideEffect::Possible;
        }
        return SideEffect::Absent;
    }

    // Accept empty initializers.
    if let Expr::Call(ast::ExprCall {
        func, arguments, ..
    }) = expr
    {
        // Ex) `list()`
        if arguments.is_empty() {
            if let Expr::Name(ast::ExprName { id, .. }) = func.as_ref() {
                if is_iterable_initializer(id.as_str(), |id| is_builtin(id)) {
                    return SideEffect::Absent;
                }
            }
        }
        return SideEffect::Present;
    }

    // Avoid false positives for overloaded operators.
    if let Expr::BinOp(ast::ExprBinOp { left, right, .. }) = expr {
        if is_simple_binop_operand(left) && is_simple_binop_operand(right) {
            return SideEffect::Absent;
        }
        return SideEffect::Present;
    }

    // Otherwise, assume all complex expressions have side effects.
    if matches!(
        expr,
        Expr::Await(_)
            | Expr::Call(_)
            | Expr::DictComp(_)
            | Expr::Generator(_)
            | Expr::ListComp(_)
            | Expr::SetComp(_)
            | Expr::Subscript(_)
            | Expr::Yield(_)
            | Expr::YieldFrom(_)
            | Expr::IpyEscapeCommand(_)
    ) {
        return SideEffect::Present;
    }

